      <a href="#work">Work</a>
      <a href="#about">About</a>
      <a href="mailto:studio@example.test">Contact</a>
    </nav>
  </header>
  <main class="shell">
    <section class="hero" aria-labelledby="hero-heading">
      <h1 id="hero-heading"><span>Make room for</span> <span>the moving world.</span></h1>
      <div class="hero-detail">
        <p class="subheading">Thoughtful films, clear stories, lasting places.</p>
        <a class="explore" href="#work">Explore the work <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 4v16m-6-6 6 6 6-6" stroke="currentColor" stroke-width="1.5"/></svg></a>
      </div>
      <div class="film" data-media>
        <img src="assets/poster.svg" alt="" width="960" height="540" fetchpriority="high">
        <video data-src="assets/scene.webm" poster="assets/poster.svg" muted playsinline loop preload="none" aria-hidden="true" hidden></video>
        <button class="media-toggle" type="button" aria-label="Play background video" data-paused="true" hidden>
          <svg class="pause-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M6 4h4v16H6zm8 0h4v16h-4z"/></svg>
          <svg class="play-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m8 4 12 8-12 8z"/></svg>
        </button>
        <span class="sr-only" data-media-status role="status"></span>
      </div>
    </section>
    <section class="work" id="work" aria-labelledby="work-heading">
      <h2 id="work-heading">Selected work</h2>
      <div class="work-list">
        <p class="work-entry">Tidal study <span class="year">/ 2026</span></p>
        <p class="work-entry">Mountain light <span class="year">/ 2025</span></p>
      </div>
    </section>
    <section class="about" id="about" aria-label="About">
      <p>An independent film practice.</p>
    </section>
  </main>
  <script>
    (() => {
      const root = document.querySelector('"'[data-media]');
      const video = root.querySelector('video');
      const button = root.querySelector('button');
      const status = root.querySelector('[data-media-status]');
      if ("'!window.matchMedia || !window.IntersectionObserver || !window.AbortController) return;
      const reduce = matchMedia('"'(prefers-reduced-motion: reduce)');
      const controller = new AbortController();
      const options = { signal: controller.signal };
      let visible = false, userPaused = false, blocked = false, failed = false, disposed = false, epoch = 0;
      const label = (paused) => {
        button.dataset.paused = String(paused);
        button.setAttribute('aria-label', paused ? 'Play background video' : 'Pause background video');
      };
      const still = () => {
        epoch++;
        video.pause();
        video.hidden = true;
        label(true);
      };
      const sync = async () => {
        button.hidden = reduce.matches || failed || disposed;
        if (disposed || reduce.matches || "'!visible || document.hidden || userPaused || blocked || failed) {
          still();
          return;
        }
        if (!video.getAttribute('"'src')) video.src = video.dataset.src;
        const attempt = ++epoch;
        try {
          await video.play();
          if (attempt "'!== epoch) return;
          video.hidden = false;
          label(false);
          status.textContent = '"'';
        } catch {
          if (attempt "'!== epoch) return;
          blocked = true;
          still();
          status.textContent = '"'Static preview. Background playback unavailable.';
        }
      };
      const observer = new IntersectionObserver(([entry]) => {
        visible = entry.isIntersecting;
        sync();
      }, { threshold: 0 });
      try {
        video.muted = true;
        button.addEventListener('click', () => {
          userPaused = "'!video.paused;
          blocked = false;
          sync();
        }, options);
        reduce.addEventListener('"'change', sync, options);
        document.addEventListener('visibilitychange', sync, options);
        video.addEventListener('error', () => {
          failed = true;
          still();
          button.hidden = true;
          status.textContent = 'Static preview. Background video unavailable.';
        }, options);
        observer.observe(root);
        window.addEventListener('pagehide', () => {
          disposed = true;
          still();
          button.hidden = true;
          observer.disconnect();
          controller.abort();
        }, options);
      } catch {
        disposed = true;
        still();
        button.hidden = true;
        observer.disconnect();
        controller.abort();
      }
    })();
  </script>
</body>
